#!/usr/bin/env python3
"""Portable archive contracts. Generated bytes; never a programmer or hardware."""

from pathlib import Path
import copy
import hashlib
import json
import random
import stat
import subprocess
import sys
import tempfile
import warnings
import zipfile

cli = Path(sys.argv[1])
checks = 0


def check(value, detail=""):
    global checks
    checks += 1
    assert value, detail


def invoke(*args, ok=True):
    p = subprocess.run([str(cli), *map(str, args)], capture_output=True, timeout=20)
    check(p.returncode == (0 if ok else 1), (args, p.stdout[-500:], p.stderr[-1000:]))
    return json.loads(p.stdout) if p.returncode == 0 and p.stdout else None


with tempfile.TemporaryDirectory(prefix="bpcb-bundle-contract-") as directory:
    root = Path(directory) / "Espaço e ação"
    root.mkdir()
    payload = bytes(range(256)) * 5
    image = root / "app.bin"
    image.write_bytes(payload)
    manifest = dict(
        schema=1,
        name="Firmware fixture",
        version="1.2.3",
        family="stm32",
        backend="openocd",
        target="stm32f1x",
        images=[dict(role="application", file=str(image), format="bin", address=0x08000000)],
    )
    mpath = root / "input.json"
    mpath.write_text(json.dumps(manifest))
    bundle = root / "complete.bpcbfirmware"
    invoke("firmware-bundle-export", mpath, bundle)
    before = bundle.read_bytes()
    invoke("firmware-bundle-export", mpath, bundle, ok=False)
    check(bundle.read_bytes() == before)
    review = invoke("firmware-bundle-inspect", bundle)
    check(review["sha256"] == hashlib.sha256(before).hexdigest())
    check(review["manifest"]["images"][0]["file"] == "images/image-00.bin")
    check(review["manifest"]["images"][0]["sha256"] == hashlib.sha256(payload).hexdigest())
    destination = root / "importado"
    result = invoke("firmware-bundle-import", bundle, destination, review["sha256"])
    check(Path(result["images"][0]["file"]).read_bytes() == payload)
    check((destination / "firmware.json").is_file())
    invoke("firmware-bundle-import", bundle, destination, review["sha256"], ok=False)
    check(Path(result["images"][0]["file"]).read_bytes() == payload)
    invoke("firmware-bundle-import", bundle, root / "wrong-hash", "0" * 64, ok=False)
    check(not (root / "wrong-hash").exists())
    image.unlink()
    invoke("firmware-bundle-inspect", bundle)
    check(Path(result["images"][0]["file"]).is_file())
    wrapper = dict(format="bpcb.firmware.bundle", schema=1, manifest=review["manifest"])
    counter = 0

    def archive(
        w=wrapper, entries=None, first="manifest.json", extra=None, compression=zipfile.ZIP_STORED
    ):
        global counter
        counter += 1
        path = root / f"bad-{counter}.bpcbfirmware"
        with warnings.catch_warnings():
            warnings.simplefilter("ignore")
            with zipfile.ZipFile(path, "w", compression=compression) as z:
                z.writestr(first, json.dumps(w, allow_nan=True).encode())
                for name, body in (
                    entries if entries is not None else [("images/image-00.bin", payload)]
                ):
                    z.writestr(name, body)
                if extra:
                    z.writestr(*extra)
        return path

    def reject(w=wrapper, **kwargs):
        p = archive(w, **kwargs)
        invoke("firmware-bundle-inspect", p, ok=False)
        digest = hashlib.sha256(p.read_bytes()).hexdigest()
        d = root / f"reject-{counter}"
        invoke("firmware-bundle-import", p, d, digest, ok=False)
        check(not d.exists())
        check(
            not list(root.glob(".bpcb-firmware-*")),
            [(str(x), list(x.rglob("*"))) for x in root.glob(".bpcb-firmware-*")],
        )

    reject(first="../manifest.json")
    reject(first="MANIFEST.JSON")
    reject(entries=[])
    reject(entries=[("images/image-00.bin", payload[:-1])])
    reject(entries=[("images/image-00.bin", payload + b"x")])
    reject(entries=[("images/image-00.bin", payload), ("images/image-00.bin", payload)])
    for name in [
        "../outside.bin",
        "/tmp/outside.bin",
        "images/../../outside.bin",
        "C:/outside.bin",
        "images\\image-00.bin",
        "images/image-01.bin",
        "images/image-00.bin/",
        "./images/image-00.bin",
    ]:
        reject(entries=[(name, payload)])
    reject(extra=("unexpected.txt", b"X"))
    reject(extra=("manifest.json", b"{}"))
    reject(entries=[("images/image-00.bin", bytes(len(payload)))])
    symlink = zipfile.ZipInfo("images/image-00.bin")
    symlink.create_system = 3
    symlink.external_attr = (stat.S_IFLNK | 0o777) << 16
    reject(entries=[(symlink, b"/tmp/never-follow")])
    for field, value in [("schema", 2), ("schema", 1.0), ("format", "other"), ("extra", True)]:
        w = copy.deepcopy(wrapper)
        w[field] = value
        reject(w)
    for field, value in [
        ("schema", 2),
        ("family", "unknown"),
        ("backend", "exec"),
        ("name", ""),
        ("target", []),
        ("images", []),
    ]:
        w = copy.deepcopy(wrapper)
        w["manifest"][field] = value
        reject(w)
    for field, value in [
        ("file", "../../outside.bin"),
        ("file", "images/image-00.hex"),
        ("format", "exe"),
        ("bytes", 0),
        ("bytes", -1),
        ("bytes", 1.5),
        ("bytes", 17 * 1024 * 1024),
        ("sha256", "0" * 64),
        ("sha256", ""),
        ("address", -1),
        ("address", 0),
        ("role", "../role"),
    ]:
        w = copy.deepcopy(wrapper)
        w["manifest"]["images"][0][field] = value
        reject(w)
    w = copy.deepcopy(wrapper)
    w["manifest"]["images"][0]["bytes"] = 17 * 1024 * 1024
    reject(
        w,
        entries=[("images/image-00.bin", b"0" * (17 * 1024 * 1024))],
        compression=zipfile.ZIP_DEFLATED,
    )
    for count in [0, 1, 10, len(before) // 2, len(before) - 10]:
        p = root / "truncated.bpcbfirmware"
        p.write_bytes(before[:count])
        invoke("firmware-bundle-inspect", p, ok=False)
    rng = random.Random(1562)
    for i in range(100):
        body = bytearray(payload)
        at = rng.randrange(len(body))
        body[at] ^= rng.randrange(1, 256)
        reject(entries=[("images/image-00.bin", body)])
    link = root / "link.bpcbfirmware"
    link.symlink_to(bundle)
    invoke("firmware-bundle-inspect", link, ok=False)
    for family, fmt, target, backend in [
        ("esp32", "bin", "esp32", "esptool"),
        ("fpga", "svf", "fixture_fpga", "openocd"),
    ]:
        f = root / f"fixture.{fmt}"
        f.write_bytes(b"fixture-data\n")
        m = copy.deepcopy(manifest)
        m.update(
            family=family,
            backend=backend,
            target=target,
            images=[dict(role="application", file=str(f), format=fmt)],
        )
        if family == "esp32":
            m["images"][0]["address"] = 0x1000
        mpath.write_text(json.dumps(m))
        out = root / f"{family}.bpcbfirmware"
        invoke("firmware-bundle-export", mpath, out)
        r = invoke("firmware-bundle-inspect", out)
        check(r["manifest"]["family"] == family)
print(
    f"{checks} verificações de pacotes completos, caminhos, hashes, limites e importação sem sobrescrita."
)
